/**
 * Tokenizer: converts input string to tokens
 */
function tokenize(s) {
  const tokens = [];
  let i = 0;

  while (i < s.length) {
    // Skip whitespace
    if (/\s/.test(s[i])) {
      i++;
      continue;
    }

    // Numbers (including decimals)
    if (/\d/.test(s[i])) {
      let num = '';
      while (i < s.length && /[\d.]/.test(s[i])) {
        num += s[i];
        i++;
      }
      tokens.push({ type: 'NUMBER', value: parseFloat(num) });
      continue;
    }

    // Operators and parentheses
    if ('+-*/^()'.includes(s[i])) {
      tokens.push({ type: s[i], value: s[i] });
      i++;
      continue;
    }

    throw new Error(`Unexpected character: ${s[i]}`);
  }

  return tokens;
}

/**
 * Parser using recursive descent
 * Precedence (lowest to highest):
 * 1. Addition/Subtraction (+, -)
 * 2. Multiplication/Division (*, /)
 * 3. Exponentiation (^) - right associative
 * 4. Unary minus
 * 5. Primary (numbers, parentheses)
 */
class Parser {
  constructor(tokens) {
    this.tokens = tokens;
    this.pos = 0;
  }

  currentToken() {
    return this.tokens[this.pos];
  }

  consume(type) {
    if (!this.currentToken() || this.currentToken().type !== type) {
      throw new Error(`Expected ${type} but got ${this.currentToken()?.type || 'EOF'}`);
    }
    const token = this.currentToken();
    this.pos++;
    return token;
  }

  parse() {
    return this.parseAddition();
  }

  // Addition and subtraction (lowest precedence, left-associative)
  parseAddition() {
    let left = this.parseMultiplication();

    while (this.currentToken() && (this.currentToken().type === '+' || this.currentToken().type === '-')) {
      const op = this.consume(this.currentToken().type).value;
      const right = this.parseMultiplication();
      left = op === '+' ? left + right : left - right;
    }

    return left;
  }

  // Multiplication and division (left-associative)
  parseMultiplication() {
    let left = this.parseExponentiation();

    while (this.currentToken() && (this.currentToken().type === '*' || this.currentToken().type === '/')) {
      const op = this.consume(this.currentToken().type).value;
      const right = this.parseExponentiation();
      left = op === '*' ? left * right : left / right;
    }

    return left;
  }

  // Exponentiation (right-associative)
  parseExponentiation() {
    let left = this.parseUnary();

    if (this.currentToken() && this.currentToken().type === '^') {
      this.consume('^');
      // Right-associative: recursively call parseExponentiation
      const right = this.parseExponentiation();
      return Math.pow(left, right);
    }

    return left;
  }

  // Unary minus and primary
  parseUnary() {
    if (this.currentToken() && this.currentToken().type === '-') {
      this.consume('-');
      return -this.parseUnary();
    }

    if (this.currentToken() && this.currentToken().type === '+') {
      this.consume('+');
      return this.parseUnary();
    }

    return this.parsePrimary();
  }

  // Primary: numbers and parenthesized expressions
  parsePrimary() {
    if (this.currentToken() && this.currentToken().type === 'NUMBER') {
      return this.consume('NUMBER').value;
    }

    if (this.currentToken() && this.currentToken().type === '(') {
      this.consume('(');
      const result = this.parseAddition();
      this.consume(')');
      return result;
    }

    throw new Error(`Unexpected token: ${this.currentToken()?.type || 'EOF'}`);
  }
}

/**
 * Evaluates an arithmetic expression string
 * @param {string} s - The expression string
 * @returns {number} - The result of the evaluation
 */
export function evaluate(s) {
  const tokens = tokenize(s);
  const parser = new Parser(tokens);
  return parser.parse();
}
